"use client";

import { useEffect, useRef } from "react";

function useSmooth(ref, onFrame, lerp = 0.1) {
  useEffect(() => {
    const el = ref.current;
    let target = el.scrollTop, raf = 0;
    const emit = () => { const max = el.scrollHeight - el.clientHeight; onFrame(el.scrollTop, max > 0 ? el.scrollTop / max : 0); };
    const tick = () => {
      const d = target - el.scrollTop;
      el.scrollTop += Math.abs(d) < 0.5 ? d : d * lerp;
      emit();
      raf = Math.abs(target - el.scrollTop) < 0.5 ? 0 : requestAnimationFrame(tick);
    };
    const onWheel = (e) => {
      const max = el.scrollHeight - el.clientHeight;
      if (!raf) target = el.scrollTop;
      if ((e.deltaY < 0 && target <= 0) || (e.deltaY > 0 && target >= max)) return;
      e.preventDefault();
      target = Math.min(max, Math.max(0, target + e.deltaY));
      if (!raf) raf = requestAnimationFrame(tick);
    };
    el.addEventListener("wheel", onWheel, { passive: false });
    el.addEventListener("scroll", () => { if (!raf) emit(); }, { passive: true });
    return () => { el.removeEventListener("wheel", onWheel); cancelAnimationFrame(raf); };
  }, []);
}

export function StickyStackCardsTailwind() {
  const ref = useRef(null);
  const cards = useRef([]);
  const items = ["Research", "Wireframes", "Visual design", "Motion pass", "Launch"];
  useSmooth(ref, (s) => cards.current.forEach((c, i) => {
    const covered = Math.min(items.length - 1 - i, Math.max(0, (s - 120 - i * 360) / 346));
    c.style.transform = `scale(${1 - covered * 0.05})`;
    c.style.filter = `brightness(${1 - Math.min(covered, 3) * 0.15})`;
  }));
  return (
    <div className="relative h-[380px] w-full overflow-hidden rounded-[20px] border border-zinc-800 bg-zinc-900 text-zinc-100">
      <div ref={ref} tabIndex={0} className="h-full overflow-y-auto px-16">
        <h3 className="flex h-40 items-center justify-center text-3xl font-bold">Stacked, not stashed</h3>
        <ol className="mx-auto max-w-xl pb-32">
          {items.map((t, i) => (
            <li key={t} ref={(n) => (cards.current[i] = n)} style={{ top: 22 + i * 14 }} className="sticky mb-[132px] h-[228px] origin-top rounded-2xl border border-zinc-700 bg-zinc-800 p-5 last:mb-0">
              <span className="text-xs text-pink-400">0{i + 1}</span>
              <p className="text-2xl font-semibold">{t}</p>
            </li>
          ))}
        </ol>
      </div>
    </div>
  );
}

