    return () => {
      ro.disconnect();
      canvas.removeEventListener("webglcontextlost", onLost);
      drawRef.current = null;
      if (!gl.isContextLost()) dispose();
    };
  }, [frag, fallback, maxDpr, rootRef, canvasRef]);

  React.useEffect(() => {
    if (!running || fallback) return;
    let raf = 0;
    let last = performance.now();
    const tick = (now: number) => {
      const dt = Math.min(0.05, (now - last) / 1000);
      last = now;
      timeRef.current += dt * speedRef.current;
      drawRef.current?.();
      raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [running, fallback]);

  React.useEffect(() => { drawRef.current?.(); }, [paramsKey]);

  return fallback;
}

export function PlasmaGradient({
  color1 = "#a855f7",
  color2 = "#38bdf8",
  color3 = "#f472b6",
  speed = 1,
  scale = 1,
  glow = 1,
  vignette = 0.6,
  height = 380,
  borderRadius = 20,
  children,
  className = "",
  style,
}: PlasmaGradientProps) {
  const rootRef = React.useRef<HTMLDivElement>(null);
  const canvasRef = React.useRef<HTMLCanvasElement>(null);
  const reduced = useReducedMotionPref();
  const inView = useInView(rootRef);
  const safeSpeed = Math.max(0, speed);
  const safeScale = Math.max(0.3, Math.min(3, scale));
  const safeGlow = Math.max(0.2, Math.min(3, glow));
  const safeVig = Math.max(0, Math.min(1, vignette));
  const c1 = hexRgb(color1, [0.66, 0.33, 0.97]);
  const c2 = hexRgb(color2, [0.22, 0.74, 0.97]);
  const c3 = hexRgb(color3, [0.96, 0.45, 0.71]);

  const fallback = useShader(
    rootRef,
    canvasRef,
    FRAG,
    () => ({ u_c1: c1, u_c2: c2, u_c3: c3, u_scale: safeScale, u_glow: safeGlow, u_vig: safeVig }),
    !reduced && inView && safeSpeed > 0,
    safeSpeed,
    [color1, color2, color3, safeScale, safeGlow, safeVig].join("|"),
    1.5,
  );

  const a = Math.min(1, 0.55 * safeGlow);
  const styleVars = {
    "--mf-pl-arcs": `conic-gradient(from 0deg at 50% 50%, transparent 0deg, ${rgba(c1, a)} 40deg, transparent 80deg, ${rgba(c2, a)} 150deg, transparent 200deg, ${rgba(c3, a)} 270deg, transparent 320deg)`,
    "--mf-pl-vig": `radial-gradient(85% 100% at 50% 50%, transparent ${(70 - safeVig * 40).toFixed(0)}%, rgba(0,0,0,${(0.2 + safeVig * 0.75).toFixed(2)}) 100%)`,
    "--mf-pl-dur": `${(14 / Math.max(0.1, safeSpeed)).toFixed(1)}s`,
    height: `${height}px`,
    borderRadius: `${borderRadius}px`,
    ...style,
  } as React.CSSProperties;

  return (
    <div ref={rootRef} style={styleVars} className={`${styles.root} ${className}`.trim()}>
      {fallback ? (
        <div aria-hidden="true" className={`${styles.fallback} ${safeSpeed === 0 ? styles.paused : ""}`.trim()}>
          <div className={styles.arcs} />
          <div className={`${styles.arcs} ${styles.arcsAlt}`} />
          <div className={styles.vignette} />
        </div>
      ) : (
        <canvas ref={canvasRef} aria-hidden="true" className={styles.canvas} />
      )}
      <div className={styles.content}>
        {children ?? (
          <div className={styles.copy}>
            <h3 className={styles.title}>Plasma Gradient</h3>
            <p className={styles.subtitle}>Electric filaments arcing through a dark charged field.</p>
          </div>
        )}
      </div>
    </div>
  );
}

.root {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  display: flex;
  width: 100%;
  border: 1px solid var(--mf-border, #2e2e38);
  background: #030208;
  color: #f5f5f7;
}

.canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  pointer-events: none;
}

.fallback {
  position: absolute;
  inset: 0;
  pointer-events: none;
  overflow: hidden;
}

.arcs {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 160%;
  aspect-ratio: 1;
  translate: -50% -50%;
  background: var(--mf-pl-arcs);
  mask-image: repeating-radial-gradient(circle at 50% 50%, #000 0 2px, transparent 3px 26px);
  -webkit-mask-image: repeating-radial-gradient(circle at 50% 50%, #000 0 2px, transparent 3px 26px);
  filter: blur(1.5px) drop-shadow(0 0 6px rgba(255, 255, 255, 0.35));
  animation: mf-pl-spin var(--mf-pl-dur, 14s) linear infinite;
}

.arcsAlt {
  width: 120%;
  opacity: 0.7;
  animation-direction: reverse;
  animation-duration: calc(var(--mf-pl-dur, 14s) * 1.6);
}

.vignette {
  position: absolute;
  inset: 0;
  background: var(--mf-pl-vig);
}

.paused .arcs {
  animation-play-state: paused;
}

@keyframes mf-pl-spin {
  to {
    rotate: 360deg;
  }
}

.content {
  position: relative;
  z-index: 1;
  display: flex;
  flex: 1;
  align-items: center;
  justify-content: center;
  padding: 2rem;
}

.copy {
  text-align: center;
  text-shadow: 0 2px 28px rgba(0, 0, 0, 0.6);
}

.title {
  margin: 0;
  font-size: 2rem;
  font-weight: 700;
  letter-spacing: -0.035em;
  color: #f8f8fb;
}

.subtitle {
  margin: 0.5rem 0 0;
  font-size: 0.9375rem;
  color: rgba(240, 240, 248, 0.78);
}

@media (prefers-reduced-motion: reduce) {
  .arcs {
    animation: none;
  }
}

