  background:
    radial-gradient(120% 70% at 50% 110%, color-mix(in srgb, var(--mf-scf-accent, #a78bfa) 22%, transparent), transparent 70%),
    var(--mf-surface, #141419);
  color: var(--mf-fg, #f4f4f6);
  container-type: inline-size;
  isolation: isolate;
}

.root *,
.root *::before,
