"use client";

import { useEffect, useRef, useState } from "react";

const items = ["Midnight Drive", "Neon Bloom", "Low Tide", "Paper Moons", "Afterglow"];
const grads = ["from-pink-400 to-blue-400", "from-violet-400 to-cyan-400", "from-blue-400 to-emerald-400", "from-cyan-400 to-amber-400", "from-emerald-400 to-rose-400"];

export function ScrollCoverflowTailwind() {
  const ref = useRef(null);
  const cards = useRef([]);
  const [active, setActive] = useState(0);
  useEffect(() => {
    const el = ref.current;
    const update = () => {
      const max = el.scrollHeight - el.clientHeight;
      const t = (max > 0 ? el.scrollTop / max : 0) * (items.length - 1);
      cards.current.forEach((c, i) => {
        const d = i - t, a = Math.abs(d), s = Math.sign(d), n = Math.min(a, 1);
        c.style.transform = `translateX(${s * (n * 150 + Math.max(0, a - 1) * 75)}px) translateZ(${-n * 180}px) rotateY(${-s * n * 55}deg)`;
        c.style.zIndex = String(100 - Math.round(a * 10));
      });
      setActive(Math.round(t));
    };
    update();
    el.addEventListener("scroll", update, { passive: true });
    return () => el.removeEventListener("scroll", update);
  }, []);
  return (
    <div ref={ref} tabIndex={0} className="h-[380px] w-full overflow-y-auto rounded-[20px] border border-zinc-800 bg-zinc-900 text-zinc-100">
      <div style={{ height: 380 + (items.length - 1) * 190 }}>
        <div className="sticky top-0 flex h-[380px] flex-col items-center justify-between py-5">
          <h3 className="text-xl font-semibold">Scroll through the collection</h3>
          <ul className="relative w-full flex-1 [perspective:900px]">
            {items.map((t, i) => (
              <li key={t} ref={(n) => (cards.current[i] = n)} className={`absolute left-1/2 top-1/2 -ml-[76px] -mt-[95px] flex h-[190px] w-[152px] items-end rounded-2xl bg-gradient-to-br p-3 font-bold text-white shadow-2xl ${grads[i]}`}>{t}</li>
            ))}
          </ul>
          <p className="text-sm">{items[active]}</p>
        </div>
      </div>
    </div>
  );
}

