"use client";

import { useEffect, useRef } from "react";

const items = ["Capture the idea", "Shape the system", "Prototype in motion", "Ship with confidence"];
const grads = ["from-pink-400 to-violet-400", "from-violet-400 to-sky-400", "from-sky-400 to-emerald-400", "from-emerald-400 to-amber-400"];

export function SplitScreenScrollTailwind() {
  const ref = useRef(null);
  const left = useRef(null);
  const right = useRef(null);
  useEffect(() => {
    const el = ref.current;
    const n = items.length;
    const update = () => {
      const max = el.scrollHeight - el.clientHeight;
      const p = max > 0 ? el.scrollTop / max : 0;
      left.current.style.transform = `translateY(${(-p * (n - 1) * 100) / n}%)`;
      right.current.style.transform = `translateY(${(-(1 - p) * (n - 1) * 100) / n}%)`;
    };
    update();
    el.addEventListener("scroll", update, { passive: true });
    return () => el.removeEventListener("scroll", update);
  }, []);
  return (
    <div ref={ref} tabIndex={0} className="h-[380px] w-full overflow-y-auto rounded-[20px] border border-zinc-800 bg-zinc-900 text-zinc-100">
      <div style={{ height: 380 * items.length }}>
        <div className="sticky top-0 grid h-[380px] grid-cols-2 overflow-hidden">
          <div ref={left}>
            {items.map((t, i) => (
              <div key={t} className="flex h-[380px] flex-col justify-center gap-2 px-10">
                <span className="text-xs text-pink-400">0{i + 1}</span>
                <h3 className="text-3xl font-bold">{t}</h3>
              </div>
            ))}
          </div>
          <div ref={right}>
            {[...items].reverse().map((t, i) => (
              <div key={t} className="h-[380px] p-3">
                <div className={`h-full rounded-2xl bg-gradient-to-br ${grads[items.length - 1 - i]}`} />
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

