"use client";

import { useEffect, useRef } from "react";

const hex = (h) => [1, 3, 5].map((i) => parseInt(h.slice(i, i + 2), 16));

export function ScrollColorShiftTailwind() {
  const ref = useRef(null);
  const sections = ["Midnight", "Ember", "Daylight", "Ultraviolet"];
  const colors = ["#0f172a", "#ea580c", "#fde68a", "#6d28d9"].map(hex);
  useEffect(() => {
    const el = ref.current;
    const update = () => {
      const f = Math.max(0, Math.min(sections.length - 1, el.scrollTop / (el.clientHeight * 0.92)));
      const i = Math.min(Math.floor(f), sections.length - 2);
      const t = f - i;
      const c = colors[i].map((v, k) => Math.round(v + (colors[i + 1][k] - v) * t));
      el.style.backgroundColor = `rgb(${c.join(" ")})`;
      el.style.color = c[0] * 0.2126 + c[1] * 0.7152 + c[2] * 0.0722 > 140 ? "#0c0c12" : "#f8f8fa";
    };
    update();
    el.addEventListener("scroll", update, { passive: true });
    return () => el.removeEventListener("scroll", update);
  }, []);
  return (
    <div ref={ref} tabIndex={0} className="h-[380px] w-full overflow-y-auto rounded-[20px] border border-zinc-800">
      {sections.map((t, i) => (
        <section key={t} className="flex h-[350px] flex-col justify-center px-16">
          <span className="font-mono text-xs uppercase opacity-70">Chapter 0{i + 1}</span>
          <h3 className="text-6xl font-extrabold tracking-tighter">{t}</h3>
        </section>
      ))}
    </div>
  );
}

