}

.lg {
  --mf-tg-h: 2.625rem;
  font-size: 0.9375rem;
}

.root[aria-disabled="true"] {
  opacity: 0.5;
}

.item {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.4375rem;
  height: var(--mf-tg-h);
  min-width: var(--mf-tg-h);
  padding: 0 0.75rem;
  border: 0;
  border-radius: 0.4375rem;
  background: transparent;
  color: var(--mf-muted, #a1a1aa);
  font: inherit;
  font-weight: 500;
  white-space: nowrap;
  cursor: pointer;
  isolation: isolate;
  -webkit-tap-highlight-color: transparent;
  transition: color 160ms ease, background-color 160ms ease;
}

.outline .item {
