"use client";

import { motion } from "motion/react";
import { useState } from "react";

const plans = [
  { value: "starter", label: "Starter", price: "$0/mo" },
  { value: "pro", label: "Pro", price: "$19/mo" },
  { value: "team", label: "Team", price: "$49/mo" },
];

export function RadioCardsTailwind() {
  const [value, setValue] = useState("pro");
  const idx = plans.findIndex((p) => p.value === value);
  const onKey = (e: React.KeyboardEvent, i: number) => {
    const d = e.key === "ArrowRight" || e.key === "ArrowDown" ? 1 : e.key === "ArrowLeft" || e.key === "ArrowUp" ? -1 : 0;
    if (!d) return;
    e.preventDefault();
    const n = (i + d + plans.length) % plans.length;
    setValue(plans[n].value);
    (e.currentTarget.parentElement?.children[n] as HTMLElement)?.focus();
  };
  return (
    <div role="radiogroup" aria-label="Choose a plan" className="grid w-full max-w-2xl grid-cols-3 gap-3">
      {plans.map((p, i) => (
        <div key={p.value} role="radio" aria-checked={p.value === value} tabIndex={i === idx ? 0 : -1} onClick={() => setValue(p.value)} onKeyDown={(e) => onKey(e, i)} className="relative cursor-pointer rounded-xl border border-zinc-800 bg-zinc-900 p-4 text-sm text-zinc-100 outline-none focus-visible:ring-2 focus-visible:ring-zinc-200">
          {p.value === value && <motion.span layoutId="rc-ring" className="pointer-events-none absolute -inset-px rounded-xl border-2 border-indigo-500" transition={{ type: "spring", stiffness: 500, damping: 38 }} />}
          <div className="font-semibold">{p.label}</div>
          <div className="mt-3 font-semibold text-zinc-400">{p.price}</div>
        </div>
      ))}
    </div>
  );
}

