"use client";

import { AnimatePresence, motion } from "motion/react";
import { useEffect, useRef, useState } from "react";

const fruits = ["Apple", "Banana", "Cherry", "Mango", "Strawberry"];

export function SelectTailwind() {
  const [open, setOpen] = useState(false);
  const [value, setValue] = useState<string>();
  const [active, setActive] = useState(0);
  const root = useRef<HTMLDivElement>(null);
  useEffect(() => {
    const close = (e: PointerEvent) => !root.current?.contains(e.target as Node) && setOpen(false);
    document.addEventListener("pointerdown", close);
    return () => document.removeEventListener("pointerdown", close);
  }, []);
  const onKey = (e: React.KeyboardEvent) => {
    if (!open && ["ArrowDown", "Enter", " "].includes(e.key)) { e.preventDefault(); setOpen(true); return; }
    if (!open) return;
    if (e.key === "ArrowDown") { e.preventDefault(); setActive((a) => Math.min(fruits.length - 1, a + 1)); }
    if (e.key === "ArrowUp") { e.preventDefault(); setActive((a) => Math.max(0, a - 1)); }
    if (e.key === "Enter" || e.key === " ") { e.preventDefault(); setValue(fruits[active]); setOpen(false); }
    if (e.key === "Escape") setOpen(false);
  };
  return (
    <div ref={root} className="relative w-60 text-sm text-zinc-100">
      <button type="button" role="combobox" aria-expanded={open} aria-controls="sel-list" aria-activedescendant={open ? `sel-${active}` : undefined} onClick={() => setOpen(!open)} onKeyDown={onKey} className="flex h-9 w-full items-center justify-between rounded-lg border border-zinc-800 bg-zinc-900 px-3 outline-none focus-visible:ring-2 focus-visible:ring-zinc-200">
        <span className={value ? "" : "text-zinc-400"}>{value ?? "Select a fruit…"}</span>
        <span aria-hidden className={`transition-transform ${open ? "rotate-180" : ""}`}>⌄</span>
      </button>
      <AnimatePresence>
        {open && (
          <motion.ul id="sel-list" role="listbox" initial={{ opacity: 0, scale: 0.96, y: -6 }} animate={{ opacity: 1, scale: 1, y: 0 }} exit={{ opacity: 0, scale: 0.97 }} transition={{ duration: 0.16 }} className="absolute inset-x-0 top-11 z-50 origin-top rounded-xl border border-zinc-800 bg-zinc-900 p-1 shadow-xl">
            {fruits.map((f, i) => (
              <li key={f} id={`sel-${i}`} role="option" aria-selected={f === value} onPointerMove={() => setActive(i)} onPointerDown={(e) => e.preventDefault()} onClick={() => { setValue(f); setOpen(false); }} className={`flex h-8 cursor-pointer items-center justify-between rounded-md px-2 ${i === active ? "bg-zinc-800" : ""}`}>
                {f}{f === value && <span className="text-indigo-400">✓</span>}
              </li>
            ))}
          </motion.ul>
        )}
      </AnimatePresence>
    </div>
  );
}

