"use client";

import { AnimatePresence, motion } from "motion/react";
import { useEffect, useRef, useState } from "react";

type Item = { id: number; name: string; progress: number };

export function FileDropzoneTailwind() {
  const [items, setItems] = useState<Item[]>([]);
  const [over, setOver] = useState(false);
  const input = useRef<HTMLInputElement>(null);
  const busy = items.some((i) => i.progress < 1);
  useEffect(() => {
    if (!busy) return;
    const t = setInterval(() => setItems((l) => l.map((i) => ({ ...i, progress: Math.min(1, i.progress + 0.04) }))), 50);
    return () => clearInterval(t);
  }, [busy]);
  const add = (files: FileList | null) => files && setItems((l) => [...l, ...Array.from(files).map((f, k) => ({ id: Date.now() + k, name: f.name, progress: 0 }))]);
  return (
    <div className="grid w-full max-w-md gap-3 text-sm text-zinc-100">
      <motion.div animate={{ scale: over ? 1.015 : 1 }} onDragOver={(e) => { e.preventDefault(); setOver(true); }} onDragLeave={() => setOver(false)} onDrop={(e) => { e.preventDefault(); setOver(false); add(e.dataTransfer.files); }} className={`flex flex-col items-center gap-1 rounded-xl border-[1.5px] border-dashed p-6 text-center ${over ? "border-solid border-indigo-500 bg-indigo-500/10" : "border-zinc-700 bg-zinc-900"}`}>
        <p className="font-semibold">{over ? "Release to upload" : "Drag & drop files here"}</p>
        <p className="text-xs text-zinc-400">PNG, JPG or PDF up to 10 MB</p>
        <button type="button" onClick={() => input.current?.click()} className="mt-3 h-8 rounded-lg border border-zinc-800 bg-zinc-800 px-3 text-xs font-medium">Browse files</button>
        <input ref={input} type="file" multiple hidden onChange={(e) => add(e.target.files)} />
      </motion.div>
      <ul className="grid gap-2">
        <AnimatePresence initial={false}>
          {items.map((i) => (
            <motion.li key={i.id} layout initial={{ opacity: 0, y: -8 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, x: 24 }} className="flex items-center gap-3 rounded-lg border border-zinc-800 bg-zinc-900 p-3">
              <div className="min-w-0 flex-1">
                <div className="truncate font-medium">{i.name}</div>
                <div role="progressbar" aria-label={`Upload progress for ${i.name}`} aria-valuenow={Math.round(i.progress * 100)} className="mt-1.5 h-1 overflow-hidden rounded-full bg-zinc-800"><div className={`h-full origin-left ${i.progress < 1 ? "bg-indigo-500" : "bg-green-500"}`} style={{ transform: `scaleX(${i.progress})` }} /></div>
              </div>
              <button type="button" aria-label={`Remove ${i.name}`} onClick={() => setItems((l) => l.filter((x) => x.id !== i.id))} className="text-zinc-500 hover:text-zinc-100">✕</button>
            </motion.li>
          ))}
        </AnimatePresence>
      </ul>
    </div>
  );
}

