"use client";

import { useState } from "react";

const ITEMS = ["Home", "Workspace", "Projects", "Components", "Breadcrumb"];

export function BreadcrumbTailwind() {
  const [open, setOpen] = useState(false);
  const hidden = ITEMS.slice(1, -2);
  const shown = [ITEMS[0], ...ITEMS.slice(-2)];
  return (
    <nav aria-label="Breadcrumb">
      <ol className="flex items-center gap-1.5 rounded-xl border border-zinc-800 bg-zinc-900 px-3.5 py-2 text-sm text-zinc-400">
        {shown.map((label, i) => (
          <li key={label} className="flex items-center gap-1.5">
            {i > 0 && <span aria-hidden className="text-zinc-600">/</span>}
            {i === shown.length - 1 ? (
              <span aria-current="page" className="font-medium text-zinc-100">{label}</span>
            ) : (
              <a href="#" className="group relative hover:text-zinc-100">{label}<span className="absolute inset-x-0 -bottom-0.5 h-px origin-right scale-x-0 bg-indigo-500 transition-transform group-hover:origin-left group-hover:scale-x-100" /></a>
            )}
            {i === 0 && (
              <span className="relative flex items-center gap-1.5">
                <span aria-hidden className="text-zinc-600">/</span>
                <button aria-haspopup="menu" aria-expanded={open} aria-label="Show more" onClick={() => setOpen(!open)} className="rounded-md px-1.5 hover:bg-zinc-800">...</button>
                {open && (
                  <ul role="menu" className="absolute left-4 top-7 min-w-40 rounded-lg border border-zinc-800 bg-zinc-900 p-1 shadow-xl">
                    {hidden.map((h) => <li key={h} role="none"><a role="menuitem" href="#" className="block rounded-md px-2.5 py-1.5 text-zinc-100 hover:bg-indigo-500/20">{h}</a></li>)}
                  </ul>
                )}
              </span>
            )}
          </li>
        ))}
      </ol>
    </nav>
  );
}

