"use client";

import { useState } from "react";
import { motion } from "motion/react";

function slots(page: number, total: number): (number | "...")[] {
  if (total <= 7) return Array.from({ length: total }, (_, i) => i + 1);
  if (page <= 4) return [1, 2, 3, 4, 5, "...", total];
  if (page >= total - 3) return [1, "...", total - 4, total - 3, total - 2, total - 1, total];
  return [1, "...", page - 1, page, page + 1, "...", total];
}

export function PaginationTailwind({ total = 12 }) {
  const [page, setPage] = useState(4);
  return (
    <nav aria-label="Pagination" className="flex items-center gap-1 text-sm font-medium">
      <button disabled={page === 1} onClick={() => setPage(page - 1)} className="h-9 rounded-lg px-3 text-zinc-400 hover:bg-zinc-800 disabled:opacity-40">Previous</button>
      {slots(page, total).map((s, i) =>
        s === "..." ? (
          <span key={i} aria-hidden className="w-9 text-center text-zinc-600">...</span>
        ) : (
          <button key={s} aria-current={s === page ? "page" : undefined} onClick={() => setPage(s)} className="relative h-9 min-w-9 rounded-lg px-1.5 text-zinc-400 aria-[current=page]:text-white">
            {s === page && <motion.span layoutId="page-dot" className="absolute inset-0 rounded-lg bg-indigo-500" />}
            <span className="relative">{s}</span>
          </button>
        ),
      )}
      <button disabled={page === total} onClick={() => setPage(page + 1)} className="h-9 rounded-lg px-3 text-zinc-400 hover:bg-zinc-800 disabled:opacity-40">Next</button>
    </nav>
  );
}

