"use client";

import { useId, useState } from "react";
import { AnimatePresence, motion } from "motion/react";

const ITEMS = [
  { q: "How do I install a component?", a: "Run the CLI with the component slug." },
  { q: "Can I restyle everything?", a: "Yes, every surface reads theme variables." },
  { q: "Is it accessible?", a: "Headers are buttons with aria-expanded." },
];

export function AccordionTailwind() {
  const id = useId();
  const [open, setOpen] = useState<number | null>(0);
  return (
    <div className="w-full max-w-lg space-y-2">
      {ITEMS.map((item, i) => (
        <div key={item.q} className="rounded-xl border border-zinc-800 bg-zinc-900">
          <h3>
            <button id={`${id}-h${i}`} aria-expanded={open === i} aria-controls={`${id}-p${i}`} onClick={() => setOpen(open === i ? null : i)} className="flex w-full items-center justify-between px-4 py-4 text-left font-medium text-zinc-100">
              {item.q}
              <motion.svg animate={{ rotate: open === i ? 180 : 0 }} width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" className="text-zinc-400"><path d="m6 9 6 6 6-6" /></motion.svg>
            </button>
          </h3>
          <AnimatePresence initial={false}>
            {open === i && (
              <motion.div id={`${id}-p${i}`} role="region" aria-labelledby={`${id}-h${i}`} initial={{ height: 0 }} animate={{ height: "auto" }} exit={{ height: 0 }} className="overflow-hidden">
                <p className="px-4 pb-4 text-zinc-400">{item.a}</p>
              </motion.div>
            )}
          </AnimatePresence>
        </div>
      ))}
    </div>
  );
}

