import { AnimatePresence, motion } from "motion/react";
import { useEffect, useRef, useState } from "react";

export function PopoverTailwind() {
  const [open, setOpen] = useState(false);
  const root = useRef<HTMLDivElement>(null);
  const trigger = useRef<HTMLButtonElement>(null);
  useEffect(() => {
    if (!open) return;
    const onDown = (e: PointerEvent) => !root.current?.contains(e.target as Node) && setOpen(false);
    const onKey = (e: KeyboardEvent) => { if (e.key === "Escape") { setOpen(false); trigger.current?.focus(); } };
    document.addEventListener("pointerdown", onDown);
    document.addEventListener("keydown", onKey);
    return () => { document.removeEventListener("pointerdown", onDown); document.removeEventListener("keydown", onKey); };
  }, [open]);
  return (
    <div ref={root} className="relative inline-flex text-sm text-zinc-100">
      <button ref={trigger} aria-haspopup="dialog" aria-expanded={open} onClick={() => setOpen(!open)} className="h-9 rounded-lg border border-zinc-800 bg-zinc-900 px-4 font-medium">Open popover</button>
      <AnimatePresence>
        {open && (
          <motion.div role="dialog" aria-label="Dimensions" className="absolute left-1/2 top-full z-50 mt-3 w-80 rounded-xl border border-zinc-800 bg-zinc-950 p-4 shadow-xl" style={{ x: "-50%", originY: 0 }} initial={{ opacity: 0, scale: 0.95, y: -6 }} animate={{ opacity: 1, scale: 1, y: 0 }} exit={{ opacity: 0, scale: 0.96 }} transition={{ duration: 0.18 }}>
            <span className="absolute -top-1.5 left-1/2 h-3 w-3 -translate-x-1/2 rotate-45 border-l border-t border-zinc-800 bg-zinc-950" />
            <h3 className="font-semibold">Dimensions</h3>
