import { AnimatePresence, motion } from "motion/react";
import { useId, useRef, useState } from "react";

export function TooltipTailwind({ content = "Add to library", label = "Hover me", delay = 400 }) {
  const id = useId();
  const [open, setOpen] = useState(false);
  const timer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  const show = (wait: number) => { clearTimeout(timer.current); timer.current = setTimeout(() => setOpen(true), wait); };
  const hide = () => { clearTimeout(timer.current); setOpen(false); };
  return (
    <span className="relative inline-flex" onMouseEnter={() => show(delay)} onMouseLeave={hide}>
      <button type="button" aria-describedby={open ? id : undefined} onFocus={() => show(0)} onBlur={hide} onKeyDown={(e) => e.key === "Escape" && hide()} className="h-9 rounded-lg border border-zinc-800 bg-zinc-900 px-4 text-sm font-medium text-zinc-100">{label}</button>
      <AnimatePresence>
        {open && (
          <span className="pointer-events-none absolute bottom-full left-1/2 mb-2 -translate-x-1/2">
            <motion.span id={id} role="tooltip" initial={{ opacity: 0, y: 4, scale: 0.96 }} animate={{ opacity: 1, y: 0, scale: 1 }} exit={{ opacity: 0 }} transition={{ duration: 0.16 }} className="relative block whitespace-nowrap rounded-md bg-zinc-100 px-2.5 py-1.5 text-xs font-medium text-zinc-900 shadow-lg">
              {content}
              <span className="absolute left-1/2 top-full -mt-1 h-2 w-2 -translate-x-1/2 rotate-45 bg-zinc-100" />
            </motion.span>
          </span>
        )}
      </AnimatePresence>
    </span>
  );
}

