"use client";

import { useEffect, useState } from "react";

export function ProgressRingTailwind({ value = 72, size = 168, thickness = 12, label = "Storage used" }) {
  const [shown, setShown] = useState(0);
  useEffect(() => { const id = requestAnimationFrame(() => setShown(value)); return () => cancelAnimationFrame(id); }, [value]);
  const r = (size - thickness) / 2;
  const c = 2 * Math.PI * r;
  return (
    <div role="progressbar" aria-valuemin={0} aria-valuemax={100} aria-valuenow={value} aria-label={label} className="relative grid place-items-center" style={{ width: size, height: size }}>
      <svg aria-hidden className="absolute inset-0 -rotate-90" width={size} height={size}>
        <circle cx={size / 2} cy={size / 2} r={r} fill="none" strokeWidth={thickness} className="stroke-zinc-800" />
        <circle cx={size / 2} cy={size / 2} r={r} fill="none" strokeWidth={thickness} strokeLinecap="round" strokeDasharray={c} strokeDashoffset={c * (1 - shown / 100)} className="stroke-indigo-500 transition-[stroke-dashoffset] duration-1000 ease-out" />
      </svg>
      <div className="text-center">
        <div className="text-4xl font-bold tabular-nums text-zinc-100">{value}<span className="text-lg text-zinc-400">%</span></div>
        <div className="text-xs text-zinc-400">{label}</div>
      </div>
    </div>
  );
}

