"use client";

import { AnimatePresence, motion } from "motion/react";
import { useState } from "react";

type Node = { label: string; children?: Node[] };
const tree: Node[] = [
  { label: "src", children: [{ label: "components", children: [{ label: "button.tsx" }, { label: "tree-view.tsx" }] }, { label: "page.tsx" }] },
  { label: "package.json" },
];

export function TreeViewTailwind() {
  const [open, setOpen] = useState<string[]>(["src"]);
  const [sel, setSel] = useState("src/page.tsx");
  const render = (nodes: Node[], level: number, prefix: string) =>
    nodes.map((n) => {
      const id = prefix ? `${prefix}/${n.label}` : n.label;
      const isOpen = open.includes(id);
      return (
        <li key={id} role="treeitem" aria-level={level} aria-selected={sel === id} aria-expanded={n.children ? isOpen : undefined} tabIndex={sel === id ? 0 : -1} className="outline-none [&:focus-visible>div]:ring-2 [&:focus-visible>div]:ring-zinc-200">
          <div onClick={() => { setSel(id); if (n.children) setOpen(isOpen ? open.filter((x) => x !== id) : [...open, id]); }} style={{ paddingLeft: (level - 1) * 16 + 6 }} className={`flex h-8 cursor-pointer items-center gap-1.5 rounded-md pr-2 text-sm ${sel === id ? "bg-indigo-500/15 text-zinc-100" : "text-zinc-400 hover:bg-zinc-800 hover:text-zinc-100"}`}>
            <span className={`w-3 text-[10px] transition-transform ${n.children ? "" : "invisible"} ${isOpen ? "rotate-90" : ""}`}>&#9654;</span>
            {n.label}
          </div>
          <AnimatePresence initial={false}>
            {n.children && isOpen && (
              <motion.ul role="group" className="overflow-hidden" initial={{ height: 0 }} animate={{ height: "auto" }} exit={{ height: 0 }} transition={{ duration: 0.22 }}>
                {render(n.children, level + 1, id)}
              </motion.ul>
            )}
          </AnimatePresence>
        </li>
      );
    });
  return <ul role="tree" aria-label="Project files" className="w-64 rounded-xl border border-zinc-800 bg-zinc-950 p-2">{render(tree, 1, "")}</ul>;
}

