"use client";

import { AnimatePresence, motion } from "motion/react";
import { useEffect, useRef, useState } from "react";

const ITEMS = [
  { label: "Profile", shortcut: "⇧⌘P" },
  { label: "Billing", shortcut: "⌘B" },
  { label: "Settings", shortcut: "⌘S" },
  { label: "Log out", shortcut: "⇧⌘Q" },
];

export function DropdownMenuTailwind() {
  const [open, setOpen] = useState(false);
  const [active, setActive] = useState(0);
  const trigger = useRef<HTMLButtonElement>(null);
  const items = useRef<Array<HTMLDivElement | null>>([]);
  useEffect(() => { if (open) items.current[active]?.focus(); }, [open, active]);
  const close = () => { setOpen(false); trigger.current?.focus(); };
  const onKey = (e: React.KeyboardEvent) => {
    const n = ITEMS.length;
    if (e.key === "ArrowDown") { e.preventDefault(); setActive((a) => (a + 1) % n); }
    else if (e.key === "ArrowUp") { e.preventDefault(); setActive((a) => (a - 1 + n) % n); }
    else if (e.key === "Home") setActive(0);
    else if (e.key === "End") setActive(n - 1);
    else if (e.key === "Escape" || e.key === "Enter" || e.key === " ") { e.preventDefault(); close(); }
    else if (e.key === "Tab") setOpen(false);
  };
  return (
    <div className="relative inline-flex text-sm text-zinc-100">
      <button ref={trigger} aria-haspopup="menu" aria-expanded={open} onClick={() => { setActive(0); setOpen(!open); }} className="h-10 rounded-lg border border-zinc-800 bg-zinc-900 px-4 font-medium">My account</button>
      <AnimatePresence>
        {open && (
          <motion.div role="menu" onKeyDown={onKey} className="absolute left-0 top-full z-50 mt-1.5 w-56 origin-top-left rounded-lg border border-zinc-800 bg-zinc-950 p-1 shadow-xl" initial={{ opacity: 0, scale: 0.95, y: -6 }} animate={{ opacity: 1, scale: 1, y: 0 }} exit={{ opacity: 0, scale: 0.97 }} transition={{ duration: 0.16 }}>
            {ITEMS.map((it, i) => (
              <div key={it.label} ref={(el) => { items.current[i] = el; }} role="menuitem" tabIndex={-1} onPointerMove={() => setActive(i)} onClick={close} className="flex h-8 items-center rounded-md px-2 outline-none focus:bg-indigo-500/15">
                {it.label}<kbd className="ml-auto font-sans text-xs tracking-widest text-zinc-500">{it.shortcut}</kbd>
              </div>
            ))}
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

