"use client";

import { useState } from "react";
import { AnimatePresence, motion } from "motion/react";

const ITEMS = [
  { label: "Products", links: ["Analytics", "Automations", "Integrations"] },
  { label: "Resources", links: ["Documentation", "Templates", "Changelog"] },
  { label: "Pricing" },
];

export function NavigationMenuTailwind() {
  const [hover, setHover] = useState<string | null>(null);
  const [open, setOpen] = useState<string | null>(null);
  const active = ITEMS.find((i) => i.label === open);
  return (
    <div className="relative w-full max-w-3xl text-sm" onMouseLeave={() => { setHover(null); setOpen(null); }}>
      <nav aria-label="Main" className="flex h-14 items-center gap-4 rounded-2xl border border-zinc-800 bg-zinc-900 px-4">
        <span className="font-semibold text-zinc-100">Foundry</span>
        <ul className="flex flex-1 gap-0.5">
          {ITEMS.map((item) => (
            <li key={item.label} className="relative" onMouseEnter={() => { setHover(item.label); setOpen(item.links ? item.label : null); }}>
              {hover === item.label && <motion.span layoutId="nav-hover" className="absolute inset-0 rounded-lg bg-zinc-800" />}
              <button aria-expanded={item.links ? open === item.label : undefined} onClick={() => setOpen(open === item.label ? null : item.label)} className="relative h-9 rounded-lg px-3 font-medium text-zinc-400 hover:text-zinc-100">{item.label}</button>
            </li>
          ))}
        </ul>
      </nav>
      <AnimatePresence>
        {active?.links && (
          <motion.ul initial={{ opacity: 0, y: -8 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -6 }} className="absolute left-24 top-16 w-64 rounded-2xl border border-zinc-800 bg-zinc-900 p-2 shadow-2xl">
            {active.links.map((l) => <li key={l}><a href="#" className="block rounded-lg px-3 py-2.5 text-zinc-100 hover:bg-indigo-500/15">{l}</a></li>)}
          </motion.ul>
        )}
      </AnimatePresence>
    </div>
  );
}

