"use client";

import * as React from "react";
import { createPortal } from "react-dom";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import styles from "../styles/context-menu.module.css";

export interface ContextMenuItem {
  /** Visible label (also the value passed to onSelect) */
  label?: string;
  /** Row kind */
  type?: "item" | "checkbox" | "separator" | "label";
  /** Keyboard shortcut hint shown on the right */
  shortcut?: string;
  /** Disable the row */
  disabled?: boolean;
  /** Initial checked state for checkbox rows */
  checked?: boolean;
  /** Nested items, turning this row into a submenu trigger */
  items?: ContextMenuItem[];
}

export interface ContextMenuProps {
  /** Menu items; defaults to a browser-style page menu */
  items?: ContextMenuItem[];
  /** Called with the label of the activated item */
  onSelect?: (label: string) => void;
  /** Text inside the dashed target area */
  areaLabel?: string;
  /** Secondary hint text inside the area */
  hint?: string;
  /** Target area width in pixels */
  width?: number;
  /** Target area height in pixels */
  height?: number;
  /** Menu panel width in pixels */
  menuWidth?: number;
  /** Accent color for checks, highlights and the focus ring */
  accentColor?: string;
  /** Show keyboard shortcut hints */
  showShortcuts?: boolean;
  /** Include items that open a submenu */
  showSubmenu?: boolean;
  /** Disable the context menu (native menu is shown instead) */
  disabled?: boolean;
  /** Optional className merged onto the root */
  className?: string;
  /** Optional inline styles merged onto the root */
  style?: React.CSSProperties;
}

const DEFAULT_ITEMS: ContextMenuItem[] = [
  { label: "Back", shortcut: "⌘[" },
  { label: "Forward", shortcut: "⌘]", disabled: true },
  { label: "Reload", shortcut: "⌘R" },
  {
    label: "More tools",
    items: [
      { label: "Save page as…", shortcut: "⇧⌘S" },
      { label: "Create shortcut…" },
      { label: "Name window…" },
      { type: "separator" },
      { label: "Developer tools", shortcut: "⌥⌘I" },
    ],
  },
  { type: "separator" },
  { type: "label", label: "View" },
  { type: "checkbox", label: "Show bookmarks bar", shortcut: "⇧⌘B", checked: true },
  { type: "checkbox", label: "Show full URLs" },
];
const THEME_TOKENS = ["--mf-bg", "--mf-fg", "--mf-surface", "--mf-surface-raised", "--mf-muted", "--mf-subtle", "--mf-border", "--mf-border-strong", "--mf-accent"];
const useIsoLayoutEffect = typeof window !== "undefined" ? React.useLayoutEffect : React.useEffect;
const clamp = (v: number, min: number, max: number) => Math.max(min, Math.min(v, max));
const isAction = (it: ContextMenuItem) => (it.type ?? "item") === "item" || it.type === "checkbox";

function readThemeVars(el: Element | null): Record<string, string> {
  const out: Record<string, string> = {};
  if (!el) return out;
  const cs = getComputedStyle(el);
  for (const t of THEME_TOKENS) {
    const v = cs.getPropertyValue(t).trim();
    if (v) out[t] = v;
  }
  return out;
}

interface Anchor {
  x: number;
  y: number;
  w: number;
  h: number;
}

interface PanelProps {
  items: ContextMenuItem[];
  anchor: Anchor;
  isSub: boolean;
  focusFirst: boolean;
  labelledBy?: string;
  showShortcuts: boolean;
  checked: Record<string, boolean>;
  layerStyle: React.CSSProperties;
  onActivate: (item: ContextMenuItem) => void;
  onCloseAll: () => void;
  onCloseSelf: () => void;
}

function MenuPanel({ items, anchor, isSub, focusFirst, labelledBy, showShortcuts, checked, layerStyle, onActivate, onCloseAll, onCloseSelf }: PanelProps) {
  const reduce = useReducedMotion();
  const id = React.useId();
  const ref = React.useRef<HTMLDivElement>(null);
  const [pos, setPos] = React.useState<{ left: number; top: number; origin: string } | null>(null);
  const [active, setActive] = React.useState(-1);
  const [sub, setSub] = React.useState<{ index: number; anchor: Anchor; focus: boolean } | null>(null);
  const enabled = items.map((it, i) => (isAction(it) && !it.disabled ? i : -1)).filter((i) => i >= 0);

  useIsoLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const w = el.offsetWidth;
    const h = el.offsetHeight;
    const vw = window.innerWidth;
    const vh = window.innerHeight;
    const pad = 8;
    const fitsRight = anchor.x + anchor.w + w <= vw - pad;
    const left = clamp(fitsRight ? anchor.x + anchor.w - (isSub ? 2 : 0) : anchor.x - w + (isSub ? 2 : 0), pad, vw - w - pad);
    const startY = isSub ? anchor.y - 5 : anchor.y;
    const fitsDown = startY + h <= vh - pad;
    const top = clamp(fitsDown ? startY : (isSub ? anchor.y + anchor.h + 5 : anchor.y) - h, pad, vh - h - pad);
    setPos({ left, top, origin: `${fitsRight ? "left" : "right"} ${fitsDown ? "top" : "bottom"}` });
    if (focusFirst && enabled.length) setActive(enabled[0]);
    else el.focus();
  }, []);

  React.useEffect(() => {
    if (active >= 0) ref.current?.querySelector<HTMLElement>(`[data-index="${active}"]`)?.focus();
  }, [active]);

  const openSub = (i: number, focus: boolean) => {
    const node = ref.current?.querySelector<HTMLElement>(`[data-index="${i}"]`);
    if (!node) return;
    const r = node.getBoundingClientRect();
    setSub({ index: i, anchor: { x: r.left, y: r.top, w: r.width, h: r.height }, focus });
  };

  const activate = (i: number, viaKey: boolean) => {
    const it = items[i];
    if (!it || !isAction(it) || it.disabled) return;
    if (it.items?.length) openSub(i, viaKey);
    else onActivate(it);
  };

  const onKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
    if (!ref.current?.contains(e.target as Node) || !enabled.length) return;
    const k = e.key;
    const at = enabled.indexOf(active);
    const move = (n: number) => {
      e.preventDefault();
      setActive(enabled[(n + enabled.length) % enabled.length]);
    };
    if (k === "ArrowDown") move(at < 0 ? 0 : at + 1);
    else if (k === "ArrowUp") move(at < 0 ? enabled.length - 1 : at - 1);
    else if (k === "Home") move(0);
    else if (k === "End") move(enabled.length - 1);
    else if (k === "Enter" || k === " ") {
      e.preventDefault();
      activate(active, true);
    } else if (k === "ArrowRight" && items[active]?.items?.length) {
      e.preventDefault();
      openSub(active, true);
    } else if (k === "ArrowLeft" && isSub) {
      e.preventDefault();
      onCloseSelf();
    } else if (k === "Escape") {
      e.preventDefault();
      e.stopPropagation();
      if (isSub) onCloseSelf();
      else onCloseAll();
    } else if (k === "Tab") {
      e.preventDefault();
      onCloseAll();
    } else if (k.length === 1 && !e.ctrlKey && !e.metaKey && !e.altKey) {
      const q = k.toLowerCase();
      const order = enabled.map((_, n) => enabled[(at + 1 + n) % enabled.length]);
      const hit = order.find((i) => items[i].label?.toLowerCase().startsWith(q));
      if (hit !== undefined) setActive(hit);
    }
  };

  return (
    <motion.div
      ref={ref}
      role="menu"
      aria-label={labelledBy ? undefined : "Context menu"}
      aria-labelledby={labelledBy}
      aria-orientation="vertical"
      tabIndex={-1}
      data-mf-cm-panel=""
      className={styles.menu}
      style={{ ...layerStyle, left: pos?.left ?? anchor.x, top: pos?.top ?? anchor.y, visibility: pos ? "visible" : "hidden", transformOrigin: pos?.origin ?? "left top" }}
      initial={reduce ? { opacity: 0 } : { opacity: 0, scale: 0.95 }}
      animate={reduce ? { opacity: 1 } : { opacity: 1, scale: 1 }}
      exit={reduce ? { opacity: 0 } : { opacity: 0, scale: 0.97, transition: { duration: 0.1 } }}
      transition={{ duration: reduce ? 0.08 : 0.15, ease: [0.16, 1, 0.3, 1] }}
      onKeyDown={onKeyDown}
      onContextMenu={(e) => e.preventDefault()}
      onPointerLeave={() => {
        if (!sub) {
          setActive(-1);
          ref.current?.focus();
        }
      }}
    >
      {items.map((it, i) => {
        const kind = it.type ?? "item";
        if (kind === "separator") return <div key={`sep-${i}`} role="separator" className={styles.separator} />;
        if (kind === "label") return <div key={`lbl-${i}`} role="presentation" className={styles.groupLabel}>{it.label}</div>;
        const hasSub = !!it.items?.length;
        const isChecked = kind === "checkbox" && !!checked[it.label ?? ""];
        return (
          <div
            key={`${it.label}-${i}`}
            id={`${id}-${i}`}
            role={kind === "checkbox" ? "menuitemcheckbox" : "menuitem"}
            aria-checked={kind === "checkbox" ? isChecked : undefined}
            aria-disabled={it.disabled || undefined}
            aria-haspopup={hasSub ? "menu" : undefined}
            aria-expanded={hasSub ? sub?.index === i : undefined}
            tabIndex={-1}
            data-index={i}
            data-active={active === i || sub?.index === i ? "" : undefined}
            className={styles.item}
            onPointerMove={() => {
              if (it.disabled) return;
              if (active !== i) setActive(i);
              if (hasSub && sub?.index !== i) openSub(i, false);
              else if (!hasSub && sub) setSub(null);
            }}
            onClick={() => activate(i, false)}
          >
            <span aria-hidden="true" className={styles.indicator}>
              {isChecked && (
                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round">
                  <motion.path d="M5 12.5l4.5 4.5L19 7.5" initial={reduce ? false : { pathLength: 0 }} animate={{ pathLength: 1 }} transition={{ duration: 0.22 }} />
                </svg>
              )}
            </span>
            <span className={styles.label}>{it.label}</span>
            {showShortcuts && it.shortcut && !hasSub && <span className={styles.shortcut}>{it.shortcut}</span>}
            {hasSub && (
              <svg aria-hidden="true" className={styles.chevron} width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                <path d="m9 6 6 6-6 6" />
              </svg>
            )}
          </div>
        );
      })}
      {createPortal(
        <AnimatePresence>
          {sub && items[sub.index]?.items && (
            <MenuPanel
              key={sub.index}
              items={items[sub.index].items ?? []}
              anchor={sub.anchor}
              isSub
              focusFirst={sub.focus}
              labelledBy={`${id}-${sub.index}`}
              showShortcuts={showShortcuts}
              checked={checked}
              layerStyle={layerStyle}
              onActivate={onActivate}
              onCloseAll={onCloseAll}
              onCloseSelf={() => {
                const i = sub.index;
                setSub(null);
                setActive(i);
                ref.current?.querySelector<HTMLElement>(`[data-index="${i}"]`)?.focus();
              }}
            />
          )}
        </AnimatePresence>,
        document.body,
      )}
    </motion.div>
  );
}

export function ContextMenu({
  items = DEFAULT_ITEMS,
  onSelect,
  areaLabel = "Right click here",
  hint = "or focus and press Shift+F10",
  width = 380,
  height = 200,
  menuWidth = 224,
  accentColor = "#6366f1",
  showShortcuts = true,
  showSubmenu = true,
  disabled = false,
  className = "",
  style,
}: ContextMenuProps) {
  const areaRef = React.useRef<HTMLDivElement>(null);
  const keyOpenedAt = React.useRef(0);
  const [mounted, setMounted] = React.useState(false);
  const [menu, setMenu] = React.useState<{ x: number; y: number; keyboard: boolean; n: number } | null>(null);
  const [themeVars, setThemeVars] = React.useState<Record<string, string>>({});
  const [last, setLast] = React.useState("");
  const list = React.useMemo(() => (showSubmenu ? items : items.filter((it) => !it.items?.length)), [items, showSubmenu]);
  const [checked, setChecked] = React.useState<Record<string, boolean>>(() => {
    const out: Record<string, boolean> = {};
    const walk = (arr: ContextMenuItem[]) => arr.forEach((it) => (it.type === "checkbox" && it.label ? (out[it.label] = !!it.checked) : it.items && walk(it.items)));
    walk(items);
    return out;
  });

  React.useEffect(() => setMounted(true), []);

  const close = React.useCallback(() => {
    setMenu(null);
    const ae = document.activeElement;
    if (!ae || ae === document.body || ae.closest("[data-mf-cm-panel]")) areaRef.current?.focus({ preventScroll: true });
  }, []);

  const openAt = (x: number, y: number, keyboard: boolean) => {
    setThemeVars(readThemeVars(areaRef.current));
    setMenu((m) => ({ x, y, keyboard, n: (m?.n ?? 0) + 1 }));
  };

  React.useEffect(() => {
    if (!menu) return;
    const onDown = (e: PointerEvent) => {
      const t = e.target as Element | null;
      if (!t?.closest?.("[data-mf-cm-panel]") && !(e.button === 2 && areaRef.current?.contains(t))) close();
    };
    const dismiss = () => close();
    document.addEventListener("pointerdown", onDown, true);
    window.addEventListener("resize", dismiss);
    window.addEventListener("blur", dismiss);
    window.addEventListener("scroll", dismiss, true);
    return () => {
      document.removeEventListener("pointerdown", onDown, true);
      window.removeEventListener("resize", dismiss);
      window.removeEventListener("blur", dismiss);
      window.removeEventListener("scroll", dismiss, true);
    };
  }, [menu, close]);

  const onKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
    if (disabled || e.target !== e.currentTarget) return;
    if (e.key === "ContextMenu" || (e.shiftKey && e.key === "F10") || e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      keyOpenedAt.current = performance.now();
      const r = e.currentTarget.getBoundingClientRect();
      openAt(r.left + 24, r.top + 24, true);
    }
  };

  const layerStyle = { ...themeVars, "--mf-cm-accent": accentColor, "--mf-cm-w": `${menuWidth}px` } as React.CSSProperties;

  return (
    <div className={`${styles.root} ${className}`.trim()} style={{ "--mf-cm-accent": accentColor, ...style } as React.CSSProperties}>
      <div
        ref={areaRef}
        role="button"
        tabIndex={disabled ? -1 : 0}
        aria-haspopup="menu"
        aria-expanded={!!menu}
        aria-disabled={disabled || undefined}
        aria-label={`${areaLabel}. ${hint}`}
        className={styles.area}
        data-open={menu ? "" : undefined}
        style={{ width, height }}
        onKeyDown={onKeyDown}
        onContextMenu={(e) => {
          if (disabled) return;
          e.preventDefault();
          if (performance.now() - keyOpenedAt.current < 400) return;
          openAt(e.clientX, e.clientY, false);
        }}
      >
        <span className={styles.areaLabel}>{areaLabel}</span>
        <span className={styles.hint}>{hint}</span>
        <span className={styles.last} aria-live="polite">
          {last ? `Last action: ${last}` : ""}
        </span>
      </div>
      {mounted &&
        createPortal(
          <AnimatePresence>
            {menu && (
              <MenuPanel
                key={menu.n}
                items={list}
                anchor={{ x: menu.x, y: menu.y, w: 0, h: 0 }}
                isSub={false}
                focusFirst={menu.keyboard}
                showShortcuts={showShortcuts}
                checked={checked}
                layerStyle={layerStyle}
                onActivate={(it) => {
                  const label = it.label ?? "";
                  if (it.type === "checkbox") setChecked((c) => ({ ...c, [label]: !c[label] }));
                  setLast(it.type === "checkbox" ? `${label} ${checked[label] ? "off" : "on"}` : label);
                  onSelect?.(label);
                  close();
                }}
                onCloseAll={close}
                onCloseSelf={close}
              />
            )}
          </AnimatePresence>,
          document.body,
        )}
    </div>
  );
}

.root {
  display: inline-flex;
  max-width: 100%;
  color: var(--mf-fg, #f4f4f6);
  font-size: 0.875rem;
}

.area {
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.25rem;
  max-width: 100%;
  padding: 1rem;
  border-radius: 0.75rem;
  border: 1.5px dashed var(--mf-border-strong, #52525b);
  background-color: color-mix(in srgb, var(--mf-surface, #141419) 60%, transparent);
  color: var(--mf-fg, #f4f4f6);
  text-align: center;
  cursor: context-menu;
  user-select: none;
  -webkit-user-select: none;
  -webkit-touch-callout: none;
  transition: border-color 160ms ease, background-color 160ms ease;
}

.area:hover,
.area[data-open] {
  border-color: var(--mf-cm-accent, #6366f1);
  background-color: color-mix(in srgb, var(--mf-cm-accent, #6366f1) 7%, var(--mf-surface, #141419));
}

.area:focus-visible {
  outline: 2px solid var(--mf-fg, #e4e4e7);
  outline-offset: 3px;
}

.area[aria-disabled="true"] {
  opacity: 0.5;
  cursor: not-allowed;
}

.areaLabel {
  font-size: 0.9375rem;
  font-weight: 500;
}

.hint {
  color: var(--mf-muted, #a1a1aa);
  font-size: 0.8125rem;
}

.last {
  min-height: 1.1rem;
  margin-top: 0.5rem;
  color: var(--mf-cm-accent, #6366f1);
  font-size: 0.75rem;
  font-weight: 500;
}

.menu {
  position: fixed;
  z-index: 1100;
  box-sizing: border-box;
  width: var(--mf-cm-w, 224px);
  max-width: calc(100vw - 16px);
  padding: 0.25rem;
  border-radius: 0.625rem;
  border: 1px solid var(--mf-border, #2e2e38);
  background-color: var(--mf-surface, #141419);
  color: var(--mf-fg, #f4f4f6);
  font-family: inherit;
  font-size: 0.875rem;
  box-shadow: 0 16px 40px -12px rgba(0, 0, 0, 0.5), 0 2px 6px rgba(0, 0, 0, 0.15);
  outline: none;
  user-select: none;
  -webkit-user-select: none;
}

.item {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  height: 2rem;
  padding: 0 0.5rem 0 0.25rem;
  border-radius: 0.375rem;
  cursor: default;
  outline: none;
  transition: background-color 100ms ease, color 100ms ease;
}

.item[data-active] {
  background-color: var(--mf-surface-raised, #1b1b22);
}

.item:focus-visible {
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--mf-cm-accent, #6366f1) 70%, transparent);
}

.item[aria-disabled="true"] {
  opacity: 0.45;
}

.indicator {
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  width: 1.125rem;
  color: var(--mf-cm-accent, #6366f1);
}

.label {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.shortcut {
  margin-left: auto;
  color: var(--mf-subtle, #71717a);
  font-size: 0.75rem;
  letter-spacing: 0.06em;
}

.chevron {
  flex-shrink: 0;
  margin-left: auto;
  color: var(--mf-muted, #a1a1aa);
}

.separator {
  height: 1px;
  margin: 0.25rem -0.25rem;
  background-color: var(--mf-border, #2e2e38);
}

.groupLabel {
  padding: 0.375rem 0.5rem 0.25rem 1.875rem;
  color: var(--mf-muted, #a1a1aa);
  font-size: 0.75rem;
  font-weight: 600;
}

@media (prefers-reduced-motion: reduce) {
  .area,
  .item {
    transition: none;
  }

  .menu {
    transform: none !important;
  }
}

components.tailwindExample:
"use client";

import { AnimatePresence, motion } from "motion/react";
import { useEffect, useRef, useState } from "react";

const ITEMS = [
  { label: "Back", shortcut: "⌘[" },
  { label: "Reload", shortcut: "⌘R" },
  { label: "Save page as…", shortcut: "⇧⌘S" },
];

export function ContextMenuTailwind() {
  const [pos, setPos] = useState<{ x: number; y: number } | null>(null);
  const menu = useRef<HTMLDivElement>(null);
  useEffect(() => {
    if (!pos) return;
    menu.current?.querySelector<HTMLElement>("[role=menuitem]")?.focus();
    const close = (e: Event) => { if (!(e.target instanceof Node && menu.current?.contains(e.target))) setPos(null); };
    document.addEventListener("pointerdown", close);
    return () => document.removeEventListener("pointerdown", close);
  }, [pos]);
  const onKey = (e: React.KeyboardEvent) => {
    const items = Array.from(menu.current?.querySelectorAll<HTMLElement>("[role=menuitem]") ?? []);
    const i = items.indexOf(document.activeElement as HTMLElement);
    if (e.key === "ArrowDown") items[(i + 1) % items.length]?.focus();
    if (e.key === "ArrowUp") items[(i - 1 + items.length) % items.length]?.focus();
    if (e.key === "Escape" || e.key === "Tab") setPos(null);
  };
  return (
    <div tabIndex={0} onContextMenu={(e) => { e.preventDefault(); setPos({ x: Math.min(e.clientX, innerWidth - 232), y: Math.min(e.clientY, innerHeight - 140) }); }} className="grid h-48 w-96 place-items-center rounded-xl border-2 border-dashed border-zinc-700 text-sm text-zinc-300">
      Right click here
      <AnimatePresence>
        {pos && (
          <motion.div ref={menu} role="menu" onKeyDown={onKey} initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }} exit={{ opacity: 0 }} transition={{ duration: 0.15 }} style={{ left: pos.x, top: pos.y, transformOrigin: "top left" }} className="fixed z-50 w-56 rounded-lg border border-zinc-800 bg-zinc-900 p-1 text-zinc-100 shadow-2xl">
            {ITEMS.map((it) => (
              <div key={it.label} role="menuitem" tabIndex={-1} onClick={() => setPos(null)} className="flex h-8 items-center rounded-md px-2 outline-none hover:bg-zinc-800 focus:bg-zinc-800">
                {it.label}<span className="ml-auto text-xs text-zinc-500">{it.shortcut}</span>
              </div>
            ))}
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

files.content:
"use client";

import * as React from "react";
import { createPortal } from "react-dom";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import styles from "../styles/alert-dialog.module.css";

export interface AlertDialogProps {
  /** Controlled open state */
  open?: boolean;
  /** Initial open state when uncontrolled */
  defaultOpen?: boolean;
  /** Called whenever the dialog requests to open or close */
  onOpenChange?: (open: boolean) => void;
  /** Called when the confirm action is pressed (the dialog then closes) */
  onConfirm?: () => void;
  /** Called when the dialog is dismissed with Cancel or Escape */
  onCancel?: () => void;
  /** Label of the trigger button */
  triggerLabel?: string;
  /** Dialog title (accessible name) */
  title?: string;
  /** Explanation of the consequences (accessible description) */
  description?: string;
  /** Label of the confirm action */
  confirmLabel?: string;
  /** Label of the cancel action (focused by default) */
  cancelLabel?: string;
  /** Destructive styling (red) or neutral styling (accent) for the confirm action */
  variant?: "destructive" | "default";
  /** Accent color used by the default variant */
  accentColor?: string;
  /** Color used by the destructive variant */
  destructiveColor?: string;
  /** Show the warning icon next to the title */
  showIcon?: boolean;
  /** Backdrop blur in pixels */
  backdropBlur?: number;
  /** Optional className merged onto the root */
  className?: string;
  /** Optional inline styles merged onto the root */
  style?: React.CSSProperties;
}

const THEME_TOKENS = ["--mf-bg", "--mf-fg", "--mf-surface", "--mf-surface-raised", "--mf-muted", "--mf-subtle", "--mf-border", "--mf-border-strong", "--mf-accent"];
const FOCUSABLE = 'a[href],button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex]:not([tabindex="-1"])';
const useIsoLayoutEffect = typeof window !== "undefined" ? React.useLayoutEffect : React.useEffect;

function readThemeVars(el: Element | null): Record<string, string> {
  const out: Record<string, string> = {};
  if (!el) return out;
  const cs = getComputedStyle(el);
  for (const t of THEME_TOKENS) {
    const v = cs.getPropertyValue(t).trim();
    if (v) out[t] = v;
  }
  return out;
}

export function AlertDialog({
  open: openProp,
  defaultOpen = false,
  onOpenChange,
  onConfirm,
  onCancel,
  triggerLabel = "Delete account",
  title = "Are you absolutely sure?",
  description = "This action cannot be undone. This will permanently delete your account and remove your data from our servers.",
  confirmLabel = "Yes, delete account",
  cancelLabel = "Cancel",
  variant = "destructive",
  accentColor = "#6366f1",
  destructiveColor = "#ef4444",
  showIcon = true,
  backdropBlur = 4,
  className = "",
  style,
}: AlertDialogProps) {
  const reduce = useReducedMotion();
  const [inner, setInner] = React.useState(defaultOpen);
  const open = openProp !== undefined ? openProp : inner;
  const setOpen = React.useCallback(
    (v: boolean) => {
      if (openProp === undefined) setInner(v);
      onOpenChange?.(v);
    },
    [openProp, onOpenChange],
  );
  const cancelRef = React.useRef(() => {});
  cancelRef.current = () => {
    onCancel?.();
    setOpen(false);
  };
  const [mounted, setMounted] = React.useState(false);
  const [themeVars, setThemeVars] = React.useState<Record<string, string>>({});
  const [nudge, setNudge] = React.useState(false);
  const rootRef = React.useRef<HTMLDivElement>(null);
  const triggerRef = React.useRef<HTMLButtonElement>(null);
  const panelRef = React.useRef<HTMLDivElement>(null);
  const cancelBtnRef = React.useRef<HTMLButtonElement>(null);
  const wasOpen = React.useRef(false);
  const id = React.useId();
  const tone = variant === "destructive" ? destructiveColor : accentColor;

  React.useEffect(() => setMounted(true), []);
  useIsoLayoutEffect(() => {
    if (open) setThemeVars(readThemeVars(rootRef.current));
  }, [open]);

  React.useEffect(() => {
    if (!nudge) return;
    const t = window.setTimeout(() => setNudge(false), 320);
    return () => window.clearTimeout(t);
  }, [nudge]);

  React.useEffect(() => {
    if (!open) {
      if (wasOpen.current) triggerRef.current?.focus();
      wasOpen.current = false;
      return;
    }
    wasOpen.current = true;
    const body = document.body;
    const prev = [body.style.overflow, body.style.paddingRight];
    const gap = window.innerWidth - document.documentElement.clientWidth;
    body.style.overflow = "hidden";
    if (gap > 0) body.style.paddingRight = `${gap}px`;
    const onKey = (e: KeyboardEvent) => {
      if (e.key !== "Escape") return;
      e.preventDefault();
      cancelRef.current();
    };
    document.addEventListener("keydown", onKey);
    const raf = requestAnimationFrame(() => (cancelBtnRef.current ?? panelRef.current)?.focus());
    return () => {
      cancelAnimationFrame(raf);
      document.removeEventListener("keydown", onKey);
      body.style.overflow = prev[0];
      body.style.paddingRight = prev[1];
    };
  }, [open]);

  const trapFocus = (e: React.KeyboardEvent<HTMLDivElement>) => {
    if (e.key !== "Tab" || !panelRef.current) return;
    const nodes = Array.from(panelRef.current.querySelectorAll<HTMLElement>(FOCUSABLE));
    if (!nodes.length) return e.preventDefault();
    const [first, last] = [nodes[0], nodes[nodes.length - 1]];
    if (e.shiftKey && (document.activeElement === first || document.activeElement === panelRef.current)) {
      e.preventDefault();
      last.focus();
    } else if (!e.shiftKey && document.activeElement === last) {
      e.preventDefault();
      first.focus();
    }
  };

  const ease = [0.16, 1, 0.3, 1] as const;

  return (
    <div ref={rootRef} className={`${styles.root} ${className}`.trim()} style={{ "--mf-ad-tone": tone, ...style } as React.CSSProperties}>
      <button ref={triggerRef} type="button" aria-haspopup="dialog" aria-expanded={open} data-variant={variant} className={styles.trigger} onClick={() => setOpen(true)}>
        {triggerLabel}
      </button>
      {mounted &&
        createPortal(
          <AnimatePresence>
            {open && (
              <div className={styles.layer} style={{ ...themeVars, "--mf-ad-tone": tone, "--mf-ad-blur": `${Math.max(0, backdropBlur)}px` } as React.CSSProperties}>
                <motion.div aria-hidden="true" className={styles.backdrop} initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} transition={{ duration: reduce ? 0.1 : 0.2 }} />
                <div
                  className={styles.center}
                  onPointerDown={(e) => {
                    if (e.target !== e.currentTarget) return;
                    e.preventDefault();
                    if (!reduce) setNudge(true);
                    cancelBtnRef.current?.focus();
                  }}
                >
                  <motion.div
                    ref={panelRef}
                    role="alertdialog"
                    aria-modal="true"
                    aria-labelledby={`${id}-title`}
                    aria-describedby={`${id}-desc`}
                    tabIndex={-1}
                    data-nudge={nudge ? "" : undefined}
                    className={styles.panel}
                    onKeyDown={trapFocus}
                    initial={reduce ? { opacity: 0 } : { opacity: 0, scale: 0.94, y: 10 }}
                    animate={reduce ? { opacity: 1 } : { opacity: 1, scale: 1, y: 0 }}
                    exit={reduce ? { opacity: 0 } : { opacity: 0, scale: 0.97, y: 4 }}
                    transition={reduce ? { duration: 0.1 } : { duration: 0.22, ease }}
                  >
                    <div className={styles.content}>
                      {showIcon && (
                        <span aria-hidden="true" className={styles.icon}>
                          <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                            <path d="M10.3 3.9 1.8 18a2 2 0 0 0 1.7 3h17a2 2 0 0 0 1.7-3L13.7 3.9a2 2 0 0 0-3.4 0zM12 9v4M12 17h.01" />
                          </svg>
                        </span>
                      )}
                      <div className={styles.text}>
                        <h2 id={`${id}-title`} className={styles.title}>
                          {title}
                        </h2>
                        <p id={`${id}-desc`} className={styles.description}>
                          {description}
                        </p>
                      </div>
                    </div>
                    <div className={styles.footer}>
                      <button ref={cancelBtnRef} type="button" className={styles.cancel} onClick={() => cancelRef.current()}>
                        {cancelLabel}
                      </button>
                      <button
                        type="button"
                        className={styles.confirm}
                        onClick={() => {
                          onConfirm?.();
                          setOpen(false);
                        }}
                      >
                        {confirmLabel}
                      </button>
                    </div>
                  </motion.div>
                </div>
              </div>
            )}
          </AnimatePresence>,
          document.body,
        )}
    </div>
  );
}

.root {
  display: inline-flex;
  color: var(--mf-fg, #f4f4f6);
}

.trigger,
.cancel,
.confirm {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 2.375rem;
  padding: 0 1rem;
  border-radius: 0.5rem;
  font: inherit;
  font-size: 0.875rem;
  font-weight: 500;
  cursor: pointer;
  transition: background-color 150ms ease, border-color 150ms ease, color 150ms ease, opacity 150ms ease, transform 150ms ease;
}

.trigger,
.cancel {
  border: 1px solid var(--mf-border, #2e2e38);
  background-color: var(--mf-surface, #141419);
  color: var(--mf-fg, #f4f4f6);
}

.trigger[data-variant="destructive"] {
  border-color: color-mix(in srgb, var(--mf-ad-tone, #ef4444) 45%, transparent);
  color: var(--mf-ad-tone, #ef4444);
}

.trigger:hover,
.cancel:hover {
  background-color: var(--mf-surface-raised, #1b1b22);
  border-color: var(--mf-border-strong, #52525b);
}

.trigger[data-variant="destructive"]:hover {
  background-color: color-mix(in srgb, var(--mf-ad-tone, #ef4444) 12%, transparent);
  border-color: var(--mf-ad-tone, #ef4444);
}

.trigger:active,
.cancel:active,
.confirm:active {
  transform: scale(0.98);
}

.confirm {
  border: 1px solid var(--mf-ad-tone, #ef4444);
  background-color: var(--mf-ad-tone, #ef4444);
  color: #ffffff;
}

.confirm:hover {
  opacity: 0.9;
}

.trigger:focus-visible,
.cancel:focus-visible,
.confirm:focus-visible {
  outline: 2px solid var(--mf-fg, #e4e4e7);
  outline-offset: 2px;
}

.layer {
  position: fixed;
  inset: 0;
  z-index: 1000;
  color: var(--mf-fg, #f4f4f6);
}

.backdrop {
  position: absolute;
  inset: 0;
  background-color: rgba(9, 9, 11, 0.6);
  backdrop-filter: blur(var(--mf-ad-blur, 4px));
  -webkit-backdrop-filter: blur(var(--mf-ad-blur, 4px));
}

.center {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  padding: 1rem;
  overflow-y: auto;
}

.panel {
  position: relative;
  box-sizing: border-box;
  width: 100%;
  max-width: 28rem;
  padding: 1.5rem;
  border-radius: 0.75rem;
  border: 1px solid var(--mf-border, #2e2e38);
  background-color: var(--mf-surface, #141419);
  color: var(--mf-fg, #f4f4f6);
  box-shadow: 0 24px 64px -16px rgba(0, 0, 0, 0.55);
  outline: none;
}

.panel[data-nudge] {
  animation: mf-ad-nudge 300ms cubic-bezier(0.36, 0, 0.3, 1);
}

@keyframes mf-ad-nudge {
  40% {
    scale: 1.025;
  }
  100% {
    scale: 1;
  }
}

.content {
  display: flex;
  align-items: flex-start;
  gap: 1rem;
}

.icon {
  display: grid;
  place-items: center;
  flex-shrink: 0;
  width: 2.5rem;
  height: 2.5rem;
  border-radius: 50%;
  background-color: color-mix(in srgb, var(--mf-ad-tone, #ef4444) 15%, transparent);
  color: var(--mf-ad-tone, #ef4444);
}

.text {
  display: grid;
  gap: 0.5rem;
  min-width: 0;
}

.title {
  margin: 0;
  font-size: 1.125rem;
  font-weight: 600;
  line-height: 1.3;
  letter-spacing: -0.01em;
}

.description {
  margin: 0;
  font-size: 0.875rem;
  line-height: 1.55;
  color: var(--mf-muted, #a1a1aa);
}

.footer {
  display: flex;
  justify-content: flex-end;
  gap: 0.5rem;
  margin-top: 1.5rem;
}

@media (max-width: 480px) {
  .footer {
    flex-direction: column-reverse;
  }
}

@media (prefers-reduced-motion: reduce) {
  .trigger,
  .cancel,
  .confirm {
    transition: none;
  }

  .panel {
    transform: none !important;
    animation: none !important;
  }
}

