"use client";

import { useState } from "react";
import { AnimatePresence, motion } from "motion/react";

const menus = { File: ["New Tab", "New Window", "Print…"], Edit: ["Undo", "Redo", "Copy", "Paste"], View: ["Reload", "Toggle Fullscreen"] };

export function MenubarTailwind() {
  const [open, setOpen] = useState<string | null>(null);
  return (
    <div role="menubar" className="inline-flex h-10 items-center gap-0.5 rounded-xl border border-zinc-800 bg-zinc-950 px-1 text-sm text-zinc-100">
      {Object.entries(menus).map(([label, items]) => (
        <div key={label} className="relative" onPointerEnter={() => open && setOpen(label)}>
          <button
            role="menuitem"
            aria-haspopup="menu"
            aria-expanded={open === label}
            onClick={() => setOpen(open === label ? null : label)}
            className="h-8 rounded-md px-3 font-medium hover:bg-zinc-900 aria-expanded:bg-zinc-900"
          >
            {label}
          </button>
          <AnimatePresence>
            {open === label && (
              <motion.div
                role="menu"
                initial={{ opacity: 0, y: -4 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -4 }}
                className="absolute left-0 top-10 z-10 min-w-48 rounded-lg border border-zinc-800 bg-zinc-950 p-1 shadow-xl"
              >
                {items.map((item) => (
                  <div key={item} role="menuitem" tabIndex={-1} onClick={() => setOpen(null)} className="rounded-md px-2 py-1.5 hover:bg-indigo-500/15">
                    {item}
                  </div>
                ))}
              </motion.div>
            )}
          </AnimatePresence>
        </div>
      ))}
    </div>
  );
}

