"use client";

import { useEffect, useState } from "react";
import { AnimatePresence, motion } from "motion/react";

const icons = ["M12 2a6 6 0 0 1 6 6v8a6 6 0 0 1-12 0V8a6 6 0 0 1 6-6z", "M13 2L4 14h7l-1 8 9-12h-7z", "M3 5h18v14H3z"];

export function RotatingIconsTailwind() {
  const [i, setI] = useState(0);
  useEffect(() => {
    const id = setInterval(() => setI((n) => (n + 1) % icons.length), 2200);
    return () => clearInterval(id);
  }, []);
  return (
    <p className="flex items-center gap-3 text-5xl font-semibold tracking-tight text-zinc-100">
      built for
      <span className="relative inline-flex h-14 w-14 items-center justify-center overflow-hidden rounded-xl border border-white/10 bg-zinc-900 [perspective:600px]">
        <AnimatePresence initial={false} mode="popLayout">
          <motion.svg key={i} initial={{ rotateX: -90, opacity: 0 }} animate={{ rotateX: 0, opacity: 1 }} exit={{ rotateX: 90, opacity: 0 }} viewBox="0 0 24 24" className="h-9 w-9" fill="none" stroke="currentColor" strokeWidth={1.75}>
            <path d={icons[i]} />
          </motion.svg>
        </AnimatePresence>
      </span>
    </p>
  );
}

